// OrderServiceServer is the server API for OrderService service.
// All implementations must embed UnimplementedOrderServiceServer
// for forward compatibility.
type OrderServiceServer interface {
	CreateOrder(context.Context, *CreateOrderReq) (*OrderInfo, error)
	GetOrder(context.Context, *GetOrderReq) (*OrderDetail, error)
	ListOrders(context.Context, *ListOrdersReq) (*ListOrdersResp, error)
	CancelOrder(context.Context, *CancelOrderReq) (*common.CommonResponse, error)
	// C 端用户删除订单（软删除）：仅终态订单可删，列表与角标统计排除，详情链路保留可达
	DeleteOrder(context.Context, *DeleteOrderReq) (*common.CommonResponse, error)
	// 后台恢复被用户软删除的订单（客服场景「我删错了，帮我找回上次买的东西」）：
	// 按 community_id 限定作用域，仅在该社区范围内把 user_deleted 复位
	RestoreOrder(context.Context, *RestoreOrderReq) (*common.CommonResponse, error)
	UpdateOrderStatus(context.Context, *UpdateOrderStatusReq) (*common.CommonResponse, error)
	// 自提订单核销：校验取货码后置为已完成（后台兜底核销 / 履约工作台核销共用）
	VerifyPickup(context.Context, *VerifyPickupReq) (*VerifyPickupResp, error)
	// 退款
	ApplyRefund(context.Context, *ApplyRefundReq) (*RefundInfo, error)
	// 后台代客退款：发起即执行（免审核），items 为空表示整单退
	AdminCreateRefund(context.Context, *AdminCreateRefundReq) (*RefundInfo, error)
	ListRefunds(context.Context, *ListRefundsReq) (*ListRefundsResp, error)
	ApproveRefund(context.Context, *ApproveRefundReq) (*common.CommonResponse, error)
	RejectRefund(context.Context, *RejectRefundReq) (*common.CommonResponse, error)
	// 重试卡在"退款中"(status=4) 的退款单：以退款单自身的 payment_no 重新发起渠道退款
	RetryRefund(context.Context, *RetryRefundReq) (*common.CommonResponse, error)
	// 恢复卡在"退款中"的退款单的自动收敛（B2）：
	// 先把 payment 侧退款流水的重试预算归零（人工核实渠道结果后重新交系统收敛），
	// 再把本侧 refunds.retry_count/last_checked_at 复位，使调度器下一轮立即重新核查。
	// 与 RetryRefund 的区别：本方法不再次触渠道出款，只恢复「问渠道结果」的节奏
	ResetRefundRetry(context.Context, *ResetRefundRetryReq) (*common.CommonResponse, error)
	GetRefundConfig(context.Context, *GetRefundConfigReq) (*RefundConfig, error)
	SaveRefundConfig(context.Context, *SaveRefundConfigReq) (*common.CommonResponse, error)
	// 统计
	GetOrderStatistics(context.Context, *GetOrderStatisticsReq) (*OrderStatisticsResp, error)
	GetSalesStatistics(context.Context, *GetSalesStatisticsReq) (*SalesStatisticsResp, error)
	GetProductRankings(context.Context, *GetProductRankingsReq) (*ProductRankingsResp, error)
	GetRevenueReport(context.Context, *GetRevenueReportReq) (*RevenueReportResp, error)
	// 用户常买商品（购物车"常买商品"列表）：按用户有效订单统计
	GetUserFrequentProducts(context.Context, *GetUserFrequentProductsReq) (*GetUserFrequentProductsResp, error)
	// 用户订单状态角标统计（C 端「我的-我的订单」红标）：按用户维度按状态聚合
	GetUserOrderStatusCounts(context.Context, *GetUserOrderStatusCountsReq) (*GetUserOrderStatusCountsResp, error)
	// 免配送费试算：按商品清单计算当前社区免配送费活动命中情况（C 端确认页展示）
	PreviewFreeShipping(context.Context, *PreviewFreeShippingReq) (*PreviewFreeShippingResp, error)
	// 收银台挂单：暂存/列表/删除（草稿不生成正式订单、不占库存，决策点⑥）
	CreatePosHeldOrder(context.Context, *CreatePosHeldOrderReq) (*PosHeldOrderInfo, error)
	ListPosHeldOrders(context.Context, *ListPosHeldOrdersReq) (*ListPosHeldOrdersResp, error)
	DeletePosHeldOrder(context.Context, *DeletePosHeldOrderReq) (*common.CommonResponse, error)
	// --- 收银台交班体系 ---
	// 开工：创建进行中班次（同操作员同社区已有进行中班次时报错）
	StartShift(context.Context, *StartShiftReq) (*PosShiftInfo, error)
	// 当前进行中班次（无则返回 statistics 为空的 PosShiftInfo，id=0 表示无进行中班次），含实时统计
	GetCurrentShift(context.Context, *GetCurrentShiftReq) (*PosShiftInfo, error)
	// 交班：生成统计快照 → 置已结束 → 返回快照
	EndShift(context.Context, *EndShiftReq) (*PosShiftInfo, error)
	// 交班记录分页（operator_id=0 本店全部班次，>0 仅该操作员）
	ListShifts(context.Context, *ListShiftsReq) (*ListShiftsResp, error)
	// --- 应用偏好（应用页「常用」，社区级单行） ---
	GetAppPreferences(context.Context, *GetAppPreferencesReq) (*AppPreferencesInfo, error)
	SaveAppPreferences(context.Context, *SaveAppPreferencesReq) (*common.CommonResponse, error)
	// --- 履约工作台（B） ---
	// 后台指派配送员（delivery_user_id=0 表示取消指派）
	AssignDelivery(context.Context, *AssignDeliveryReq) (*common.CommonResponse, error)
	// 工作台查单：送货单按指派人过滤，自提单为本社区全部待核销/已核销
	ListFulfillmentOrders(context.Context, *ListFulfillmentOrdersReq) (*ListFulfillmentOrdersResp, error)
	// 开始配送：status 2/3 → 4（履约人员操作，不经后台 ShipOrder 的物流单号校验）
	StartDelivery(context.Context, *StartDeliveryReq) (*common.CommonResponse, error)
	// 送达完成：status 4 → 5，强制签收照片（决策点②拍照留证）
	CompleteDelivery(context.Context, *CompleteDeliveryReq) (*common.CommonResponse, error)
	mustEmbedUnimplementedOrderServiceServer()
}

